package dev.elpsy.ticket;

import dev.elpsy.ticket.identity.*;
import dev.elpsy.ticket.customer.*;
import dev.elpsy.ticket.common.ApiErrors.Problem;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.Cookie;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=false","ticket.admission.enabled=false","ticket.expiry.enabled=false","ticket.mock-payments.enabled=false","server.servlet.session.cookie.secure=true"})
@AutoConfigureMockMvc
class StaffSessionIntegrationTest {
 @Autowired org.springframework.transaction.PlatformTransactionManager transactions;
 @Autowired StaffSessionService service;@Autowired CustomerService customers;@Autowired JdbcTemplate db;@Autowired PasswordEncoder passwords;@Autowired MockMvc mvc;@Autowired ObjectMapper json;
 private final String password=UUID.randomUUID().toString();
 private record Account(UUID id,String name) {}
 private Account account(String role){var a=new Account(UUID.randomUUID(),"staff-"+UUID.randomUUID());db.update("INSERT INTO staff_account(id,username,password_hash,role) VALUES(?,?,?,?)",a.id(),a.name(),passwords.encode(password),role);return a;}
 private String login(Account a){return service.login(a.name(),password,null).token();}
 private Cookie cookie(String token){return new Cookie(StaffSessionFilter.COOKIE,token);}
 private record Csrf(Cookie cookie,String header,String token) {}
 private Csrf csrf(String prefix,String name)throws Exception{var r=mvc.perform(get(prefix+"/csrf")).andExpect(status().isOk()).andReturn();var b=json.readTree(r.getResponse().getContentAsString());return new Csrf(r.getResponse().getCookie(name),b.get("headerName").asText(),b.get("token").asText());}
 private Csrf csrf()throws Exception{return csrf("/api/auth","TICKET_STAFF_CSRF");}
 private MockHttpServletRequestBuilder postCsrf(String path)throws Exception{var c=csrf();return post(path).cookie(c.cookie()).header(c.header(),c.token());}
 private MockHttpServletRequestBuilder form(Account a)throws Exception{return postCsrf("/api/auth/login").contentType("application/x-www-form-urlencoded").param("username",a.name()).param("password",password);}
 private void deny(Runnable call){assertEquals(401,assertThrows(Problem.class,call::run).status);}
 @BeforeEach void ownDb(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));}
 @Test void hashedOnlyStructuredSessionAndDbDeadline(){var a=account("MANAGER");String token=login(a);assertEquals(43,token.length());assertNotEquals(token,StaffSessionService.hash(token));assertEquals(1,db.queryForObject("SELECT count(*) FROM staff_session WHERE token_hash=? AND staff_id=? AND expires_at=created_at+interval '30 minutes'",Integer.class,StaffSessionService.hash(token),a.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM staff_session WHERE token_hash=?",Integer.class,token));assertEquals(a.name(),service.authenticate(token).orElseThrow().getName());}
 @Test void freshServiceInstanceUsesSamePgSession(){var a=account("MANAGER");String token=login(a);var other=new StaffSessionService(db,passwords);assertEquals(service.authenticate(token),other.authenticate(token));other.logout(token);assertTrue(service.authenticate(token).isEmpty());}
 @Test void dbExpiryImmediateAndExclusive(){var a=account("MANAGER");String token=login(a);db.update("WITH stamp AS MATERIALIZED(SELECT clock_timestamp() AS t) UPDATE staff_session SET created_at=stamp.t-interval '30 minutes',expires_at=stamp.t FROM stamp WHERE token_hash=?",StaffSessionService.hash(token));assertTrue(service.authenticate(token).isEmpty());}
 @Test void disableReenableWithoutIntermediateRequestCannotRevive(){var a=account("MANAGER");String token=login(a);db.update("UPDATE staff_account SET enabled=false WHERE id=?",a.id());db.update("UPDATE staff_account SET enabled=true WHERE id=?",a.id());assertTrue(service.authenticate(token).isEmpty());assertEquals(3L,db.queryForObject("SELECT session_version FROM staff_account WHERE id=?",Long.class,a.id()));assertTrue(service.authenticate(login(a)).isPresent());}
 @Test void disabledCannotLogin(){var a=account("MANAGER");db.update("UPDATE staff_account SET enabled=false WHERE id=?",a.id());deny(()->login(a));assertEquals(0,db.queryForObject("SELECT count(*) FROM staff_session WHERE staff_id=?",Integer.class,a.id()));}
 @Test void roleRoundTripRevokesAndFreshRoleIsReadOnly(){var a=account("MANAGER");String token=login(a);db.update("UPDATE staff_account SET role='VIEWER' WHERE id=?",a.id());assertTrue(service.authenticate(token).isEmpty());String viewer=login(a);assertEquals("VIEWER",service.authenticate(viewer).orElseThrow().role());db.update("UPDATE staff_account SET role='MANAGER' WHERE id=?",a.id());assertTrue(service.authenticate(viewer).isEmpty());assertTrue(service.authenticate(token).isEmpty());}
 @Test void passwordReplacementRevokes(){var a=account("MANAGER");String token=login(a),replacement=UUID.randomUUID().toString();db.update("UPDATE staff_account SET password_hash=? WHERE id=?",passwords.encode(replacement),a.id());assertTrue(service.authenticate(token).isEmpty());deny(()->login(a));assertTrue(service.authenticate(service.login(a.name(),replacement,null).token()).isPresent());}
 @Test void usernameReplacementRevokesAndCurrentNameOnly(){var a=account("MANAGER");String token=login(a),replacement="staff-"+UUID.randomUUID();db.update("UPDATE staff_account SET username=? WHERE id=?",replacement,a.id());assertTrue(service.authenticate(token).isEmpty());deny(()->login(a));assertEquals(replacement,service.authenticate(service.login(replacement,password,null).token()).orElseThrow().username());}
 @Test void versionCannotDecreaseOrRevive(){var a=account("MANAGER");String token=login(a);db.update("UPDATE staff_account SET session_version=session_version+1 WHERE id=?",a.id());assertTrue(service.authenticate(token).isEmpty());assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE staff_account SET session_version=1 WHERE id=?",a.id()));}
 @Test void concurrentLoginCapIsGlobalAcrossServiceInstances()throws Exception {
  var a=account("MANAGER");String old=login(a);var other=new StaffSessionService(db,passwords);
  // A plain Java instance is not Spring-proxied. Both simulated APIs must retain
  // their account row lock through pruning and insertion in a real transaction.
  var tx=new org.springframework.transaction.support.TransactionTemplate(transactions);
  try(var pool=Executors.newFixedThreadPool(6)) {
   var start=new CountDownLatch(1);var tasks=new ArrayList<Callable<String>>();
   for(int i=0;i<6;i++){var api=i%2==0?service:other;tasks.add(()->{start.await();return tx.execute(status->api.login(a.name(),password,null).token());});}
   var futures=new ArrayList<Future<String>>();for(var task:tasks)futures.add(pool.submit(task));start.countDown();
   for(var result:futures)assertEquals(43,result.get().length());
  }
  assertEquals(5,db.queryForObject("SELECT count(*) FROM staff_session WHERE staff_id=?",Integer.class,a.id()));assertTrue(service.authenticate(old).isEmpty());
 }

 @Test void rotationIsAtomicAndOldTokenRevoked(){var a=account("MANAGER");String old=login(a),fresh=service.login(a.name(),password,old).token();assertNotEquals(old,fresh);assertTrue(service.authenticate(old).isEmpty());assertTrue(service.authenticate(fresh).isPresent());assertEquals(1,db.queryForObject("SELECT count(*) FROM staff_session WHERE staff_id=?",Integer.class,a.id()));}
 @Test void loginWriteFailureRollsBackRotation(){var a=account("MANAGER");String old=login(a);db.execute("ALTER TABLE staff_session ADD CONSTRAINT m5_session_fault CHECK(false) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->service.login(a.name(),password,old));assertTrue(service.authenticate(old).isPresent());assertEquals(1,db.queryForObject("SELECT count(*) FROM staff_session WHERE staff_id=?",Integer.class,a.id()));}finally{db.execute("ALTER TABLE staff_session DROP CONSTRAINT m5_session_fault");}assertTrue(service.authenticate(service.login(a.name(),password,old).token()).isPresent());}
 @Test void directSqlWrongRoleOrVersionCannotIssue(){var a=account("MANAGER");for(String role:List.of("VIEWER","MANAGER")){long version=role.equals("MANAGER")?2:1;assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("INSERT INTO staff_session(token_hash,staff_id,session_version,role_snapshot,expires_at) VALUES(?,?,?, ?,clock_timestamp()+interval '30 minutes')","0".repeat(64),a.id(),version,role));}}
 @Test void malformedLegacyAndDeletedTokensDenied(){for(String token:Arrays.asList(null,"","old-tomcat-session",UUID.randomUUID().toString(),"A".repeat(43)))assertTrue(service.authenticate(token).isEmpty());var a=account("MANAGER");String token=login(a);service.logout(token);service.logout(token);assertTrue(service.authenticate(token).isEmpty());}
 @Test void csrfReadDoesNotCreateHttpSessionAndHasPrivateCookie()throws Exception{var r=mvc.perform(get("/api/auth/csrf")).andExpect(status().isOk()).andReturn();assertNull(r.getRequest().getSession(false));var c=r.getResponse().getCookie("TICKET_STAFF_CSRF");assertNotNull(c);assertTrue(c.isHttpOnly());assertTrue(c.getSecure());assertEquals("/api",c.getPath());assertNull(r.getResponse().getCookie(StaffSessionFilter.COOKIE));assertEquals("X-STAFF-CSRF",json.readTree(r.getResponse().getContentAsString()).get("headerName").asText());}
 @Test void realFormLoginRotatesCookieAndClearsLegacyRoot()throws Exception{var a=account("MANAGER");var r=mvc.perform(form(a)).andExpect(status().isOk()).andExpect(jsonPath("$.authenticated").value(true)).andReturn();assertNull(r.getRequest().getSession(false));var c=Arrays.stream(r.getResponse().getCookies()).filter(x->x.getName().equals(StaffSessionFilter.COOKIE)&&"/api".equals(x.getPath())).findFirst().orElseThrow();assertTrue(c.isHttpOnly());assertTrue(c.getSecure());assertEquals(1800,c.getMaxAge());assertTrue(r.getResponse().getHeaders("Set-Cookie").stream().anyMatch(s->s.contains("SameSite=Strict")));assertTrue(r.getResponse().getHeaders("Set-Cookie").stream().anyMatch(s->s.startsWith(StaffSessionFilter.COOKIE+"=")&&s.contains("Path=/;")&&s.contains("Max-Age=0")));mvc.perform(get("/api/auth/me").cookie(c)).andExpect(status().isOk()).andExpect(jsonPath("$.username").value(a.name())).andExpect(jsonPath("$.canWrite").value(true)).andExpect(jsonPath("$.token").doesNotExist());}
 @Test void loginRejectsKnownUnknownWrongDisabledUniformly()throws Exception{var a=account("MANAGER");for(String name:List.of(a.name(),"missing-"+UUID.randomUUID()))mvc.perform(postCsrf("/api/auth/login").contentType("application/x-www-form-urlencoded").param("username",name).param("password",UUID.randomUUID().toString())).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.message").value("登入失敗"));db.update("UPDATE staff_account SET enabled=false WHERE id=?",a.id());mvc.perform(form(a)).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.message").value("登入失敗"));}
 @Test void realSessionViewerCannotWrite()throws Exception{var a=account("VIEWER");var c=cookie(login(a));mvc.perform(get("/api/admin/events").cookie(c)).andExpect(status().isOk());mvc.perform(postCsrf("/api/admin/events").cookie(c).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(get("/api/auth/me").cookie(c)).andExpect(jsonPath("$.canWrite").value(false));}
 @Test void csrfRequiredForLoginLogoutAndMutations()throws Exception{var a=account("MANAGER");String token=login(a);for(String path:List.of("/api/auth/login","/api/auth/logout","/api/admin/events"))mvc.perform(post(path).cookie(cookie(token)).contentType("application/x-www-form-urlencoded").param("username",a.name()).param("password",password)).andExpect(status().isForbidden());assertTrue(service.authenticate(token).isPresent());}
 @Test void csrfRealmsCannotCross()throws Exception{var a=account("MANAGER");var customer=csrf("/api/customer/auth","TICKET_CUSTOMER_CSRF");mvc.perform(post("/api/auth/login").cookie(customer.cookie()).header(customer.header(),customer.token()).contentType("application/x-www-form-urlencoded").param("username",a.name()).param("password",password)).andExpect(status().isForbidden());var staff=csrf();mvc.perform(post("/api/customer/auth/logout").cookie(staff.cookie()).header(staff.header(),staff.token()).contentType("application/json").content("{}")).andExpect(status().isForbidden());}
 @Test void realStaffAndCustomerCookiesIndependentAndLogoutDoesNotRevokeCustomer()throws Exception{var a=account("MANAGER");String token=login(a);var c=customers.register("session-"+UUID.randomUUID().toString().substring(0,28),"合成",password);var cc=new Cookie(CustomerAuthenticationFilter.COOKIE,c.token());mvc.perform(get("/api/auth/me").cookie(cc)).andExpect(status().isUnauthorized());mvc.perform(get("/api/customer/auth/me").cookie(cookie(token))).andExpect(status().isUnauthorized());mvc.perform(postCsrf("/api/auth/logout").cookie(cookie(token),cc)).andExpect(status().isOk());assertTrue(service.authenticate(token).isEmpty());assertTrue(customers.authenticate(c.token()).isPresent());}
 @Test void expectedActorCannotSupplyOrSwitchIdentity()throws Exception{var a=account("MANAGER");var b=account("MANAGER");String token=login(b);mvc.perform(get("/api/auth/me").header("X-Expected-Staff-Username",a.name())).andExpect(status().isUnauthorized());mvc.perform(postCsrf("/api/auth/logout").cookie(cookie(token)).header("X-Expected-Staff-Username",a.name())).andExpect(status().isUnauthorized());assertTrue(service.authenticate(token).isPresent());mvc.perform(get("/api/auth/me").cookie(cookie(token)).header("X-Expected-Staff-Username",b.name())).andExpect(status().isOk());}
 @Test void legacyMemorySessionAndDuplicateCookiesCannotAuthenticate()throws Exception{var a=account("MANAGER");String token=login(a);mvc.perform(get("/api/auth/me").cookie(cookie(token),cookie(token))).andExpect(status().isUnauthorized());mvc.perform(get("/api/auth/me").cookie(cookie("old-tomcat-id"))).andExpect(status().isUnauthorized());}
 @Test void strictLoginFormCannotSupplyRolesOrDuplicateCredentials()throws Exception{var a=account("MANAGER");mvc.perform(form(a).param("role","MANAGER")).andExpect(status().isBadRequest());mvc.perform(form(a).param("username",a.name(),a.name())).andExpect(status().isBadRequest());assertEquals(0,db.queryForObject("SELECT count(*) FROM staff_session WHERE staff_id=?",Integer.class,a.id()));}
 @Test void missingPgNeverFallsBackToMemory()throws Exception{var a=account("MANAGER");String token=login(a);db.execute("ALTER TABLE staff_session RENAME TO m5_unavailable_session");try{mvc.perform(get("/api/auth/me").cookie(cookie(token))).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("AUTH_UNAVAILABLE"));}finally{db.execute("ALTER TABLE m5_unavailable_session RENAME TO staff_session");}mvc.perform(get("/api/auth/me").cookie(cookie(token))).andExpect(status().isOk());}
}
